"""Standalone, phone-readable review of one v4 owner's export."""
import json,html,shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[2];OUT=ROOT/'product/playtests/pilot-v4-owner-2026-10-20';r=json.loads((OUT/'review.json').read_text());s=r['summary'];e=html.escape
label={'easy':'Легко','normal':'Нормально','hard':'Трудно','fun':'Интересно','okay':'Нормально','boring':'Скучно','planned':'Думал об очереди','colour-only':'Шёл по цветам','yes':'Узнаётся','no':'Не узнаётся'}
def secs(ms):return f'{ms/1000:.1f}'.replace('.',',')
cards=[]
for level in r['levels']:
 a=level['win'];v=a['ratings'];total=a['elapsedMs'];b=a['timeBuckets'];kind='fun' if v['interest']=='fun' else 'boring' if v['interest']=='boring' else 'okay';bars=''.join(f'<i class="{k}" style="width:{b[k]/total*100:.5f}%"></i>' for k in ['choice','blockedWorking','autoTail'])
 notes=''.join('<blockquote>'+e(n['note'])+'</blockquote>' for n in level['notes'])
 deaths=[x for x in r['attempts'] if x['level']==level['level'] and x['firstFatal']]
 detail=''.join(f'<li>Попытка {x["id"]}: первая необратимая ошибка на действии {x["firstFatal"]["action"]}; выбранный ход сразу снял {x["firstFatal"]["immediateClears"]} клеток. В предшествующем состоянии найдено выигрышных альтернатив: {len(x["firstFatal"]["winningAlternatives"])}.</li>' for x in deaths)
 detail=('<details><summary>Почему проигрывались попытки</summary><ul>'+detail+'</ul><p class="small">Анализ полного истинного состояния. Он не доказывает, что все последствия были понятны по видимой очереди.</p></details>')if detail else ''
 cards.append(f'''<article data-kind="{kind}" data-art="{v['art']}"><header><div><span class="num">L{level['level']}</span><h3>{e(level['title'])}</h3></div><span class="tag {kind}">{label[v['interest']]}</span></header><p>{level['attempts']} попыток · {level['losses']} поражений · {label[v['difficulty']]} · {label[v['planning']]}</p><p class="small">Рисунок: {label[v['art']]} · Победная попытка: записано {secs(total)} с</p><div class="bar">{bars}</div><p class="times">Ввод доступен {secs(b['choice'])} с · ожидание {secs(b['blockedWorking'])} с · автохвост {secs(b['autoTail'])} с</p>{notes}{detail}</article>''')
css='''*{box-sizing:border-box}html{background:#edf0e5;color:#30473a;font:16px/1.55 system-ui,sans-serif}body{margin:0}main{max-width:1000px;margin:auto;padding:24px 16px 64px}h1{font-size:clamp(28px,5vw,44px);line-height:1.12;margin:8px 0 20px}h2{font-size:25px;line-height:1.2}h3{font-size:18px;margin:3px 0}p{margin:10px 0}.eyebrow{font-size:12px;letter-spacing:.08em;color:#62734d}.lead{font-size:19px;max-width:780px}.stats,.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.stats{grid-template-columns:repeat(4,minmax(0,1fr));margin:24px 0}.stat,section,article{background:#fffcf3;border:1px solid #d3dcc5;border-radius:18px;padding:20px}.stat strong{display:block;font-size:30px}.stat span{font-size:12px;color:#66725e}section{margin:20px 0}li+li{margin-top:9px}ol,ul{padding-left:22px}.small,.times{font-size:12px;color:#65715f}.warning{background:#fff0cd;border-color:#e7d3a8}.tag{border-radius:18px;padding:5px 10px;font-size:12px;white-space:nowrap}.fun{background:#dfeccb}.boring{background:#f0d9cf}.okay{background:#ede8d9}article{padding:17px}article header{display:flex;justify-content:space-between;gap:12px;align-items:flex-start}.num{font-size:12px;color:#788465;font-weight:700}article p{font-size:13px}.bar{display:flex;height:12px;border-radius:10px;overflow:hidden;background:#e7ebdf;margin-top:16px}.bar i{height:100%}.choice{background:#87b681}.blockedWorking{background:#d1a26b}.autoTail{background:#84adbe}.legend{display:flex;gap:16px;flex-wrap:wrap;font-size:12px}.legend b{display:inline-block;width:10px;height:10px;margin-right:4px}.filters{display:flex;flex-wrap:wrap;gap:8px;position:sticky;top:0;background:#edf0e5ed;padding:12px 0;z-index:2}button{min-height:44px;padding:8px 13px;border:1px solid #bfcab2;border-radius:12px;background:#fffcf3;color:inherit;font:inherit;font-size:13px;cursor:pointer}button[aria-pressed=true]{background:#3d704b;color:white}button:focus-visible{outline:3px solid #2b83a6}blockquote{border-left:3px solid #9dbd79;margin:14px 0 0;padding:5px 0 5px 12px;font-size:13px;white-space:pre-line}details{font-size:13px;margin-top:14px;border-top:1px solid #dfe5d4;padding-top:12px}summary{cursor:pointer;min-height:44px;padding:9px 0}a{color:#28705c}footer{font-size:12px;color:#65715f;margin:28px 0}[hidden]{display:none!important}@media(max-width:620px){.stats{grid-template-columns:repeat(2,minmax(0,1fr))}.grid{grid-template-columns:1fr}section{padding:17px}.lead{font-size:17px}}'''
page=f'''<!doctype html><html lang="ru"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#edf0e5"><title>Bloomlings · разбор ручного теста v4</title><style>{css}</style><main><span class="eyebrow">BLOOMLINGS · РУЧНОЙ ТЕСТ V4 · 20 ОКТЯБРЯ</span><h1>Картинки читаются.<br>Интерес возникает там, где нужна подготовка.</h1><p class="lead">Все 30 пройдены. Сильные задачи уже есть, но до первого Hard игра всё ещё часто сводится к выбору цвета. Дольше очищать поле — не то же самое, что интереснее решать.</p><div class="stats"><div class="stat"><strong>28/30</strong><span>рисунков узнаются</span></div><div class="stat"><strong>6</strong><span>уровней «интересно»</span></div><div class="stat"><strong>7</strong><span>уровней «скучно»</span></div><div class="stat"><strong>48</strong><span>попыток: 30 побед / 18 поражений</span></div></div><section><h2>Что сохраняем</h2><p><b>L10, L15, L21, L22, L25, L29</b> получили «интересно» и «думал об очереди». На L10 и L21 понадобилось по шесть попыток; обе задачи получили положительные заметки. При этом L22 понравился с первой попытки: количество проигрышей само по себе не определяет интерес.</p><p><b>28 рисунков узнаются.</b> Точечно переделать L17 «Садовый сапог» и L20 «Пингвин»; нет основания снова менять все картинки.</p></section><section><h2>Что мешает</h2><p><b>L1–9 — девять побед с первой попытки.</b> L2/7/8/9 названы скучными. В L10 первый же полезный на вид выбор мог необратимо лишить победы: нужен более плавный переход к подготовке очереди.</p><p><b>Скучные: L2, L7, L8, L9, L13, L16, L17.</b> Некоторые занимали больше минуты, поэтому увеличение времени не решает их проблему. Короткие передышки нужны; длинные простые проходы — кандидаты на переработку.</p><p><b>Поток курьеров ограничен нами.</b> Сейчас на одну капсулу выделено максимум два работника, каждый ждёт своего полного возврата. HTML не требует такого лимита. Запрошен другой принцип: новая доступная незарезервированная клетка → новый курьер, с небольшим интервалом выхода и параллельной работой капсул.</p></section><section class="warning"><h2>Время читать осторожно</h2><p>На L9 включён ручной 2× и сохранён до конца. Позднее «авто2×» отмечает конец очереди, а не ускорение до4×. Оценка темпа заполнена только на L1–5.</p><p>В победных попытках записано {secs(s['winningTimeBuckets']['blockedWorking'])} с ожидания работы и {secs(s['winningTimeBuckets']['autoTail'])} с хвоста после очереди — около40% зарегистрированного времени. Это сигнал для разбора, не точная доля скуки.</p><p>Найден дефект таймера: при возвращении из скрытой вкладки пауза могла попасть во «время игры». Точную поправку восстановить нельзя: события видимости не записывались. Поэтому ниже показаны <b>записанные секунды</b>, а не нормализованное активное время или время размышления.</p></section><section><h2>Порядок следующей итерации</h2><ol><li>Поток курьеров с резервированием клетки, небольшим интервалом, параллельными капсулами и освобождением места после обязательных возвратов. Проверить лимиты отрисовки отдельно от игровой скорости.</li><li>Сохранить шесть удачных задач для контроля нового темпа. Подготовить мягкие зависимости до L10: запас места, маленькая/большая команда одного цвета, связка, которую полезно отложить.</li><li>Переработать длинные простые L7/9/17 и лёгкий L13. Оставить короткие передышки, включая L16, вместо превращения каждого Normal в Hard.</li><li>Перерисовать два неузнанных силуэта. Проверить маленький реальный размер клеток.</li><li>Исправить учёт скрытой вкладки; записывать скорость в начале попытки и все pause/resume. После смены потока заново измерить ожидание, не подгоняя каждый уровень под90с.</li></ol></section><h2>Все 30 уровней</h2><p class="small">Оценки относятся к победным попыткам. Время — по экспорту с описанными ограничениями. «Ввод доступен» означает допустимый ход; это не гарантирует наличие полезного выбора.</p><div class="legend"><span><b class="choice"></b>ввод доступен</span><span><b class="blockedWorking"></b>нет хода, идёт работа</span><span><b class="autoTail"></b>хвост после очереди</span></div><nav class="filters" aria-label="Фильтры уровней"><button data-filter="all" aria-pressed="true">Все30</button><button data-filter="fun" aria-pressed="false">Интересные6</button><button data-filter="boring" aria-pressed="false">Скучные7</button><button data-filter="art" aria-pressed="false">Рисунок не узнался2</button></nav><div class="grid">{''.join(cards)}</div><footer>Один возвращающийся участник. Воспроизведены все48 попыток,617 принятых и103 отклонённых нажатия; все20762 рейса совпали. Версии и хеши соответствуют финальной v4. Это не статистика аудитории или удержания. Первые необратимые ошибки проверены полным поиском; незавершённых поисков нет.</footer></main><script>document.querySelectorAll('[data-filter]').forEach(b=>b.addEventListener('click',()=>{{document.querySelectorAll('[data-filter]').forEach(x=>x.setAttribute('aria-pressed',String(x===b)));document.querySelectorAll('article').forEach(x=>x.hidden=b.dataset.filter==='all'?false:b.dataset.filter==='art'?x.dataset.art!=='no':x.dataset.kind!==b.dataset.filter);}}));</script></html>'''
for a,b in {'до4×':'до 4×','около40%':'около 40%','под90с':'под 90 с','Все30':'Все 30','Интересные6':'Интересные 6','Скучные7':'Скучные 7','узнался2':'узнался 2','все48':'все 48','попыток,617':'попыток, 617','и103':'и 103','все20762':'все 20 762'}.items():page=page.replace(a,b)
(OUT/'index.html').write_text(page);shared=Path('/workspace/shared');shared.mkdir(exist_ok=True);shutil.copyfile(OUT/'index.html',shared/'Bloomlings-v4-review.html');print(OUT/'index.html')
